"""Individually authored Angolan Portuguese A1 chapters 4–15 and extension chapters 91–92.

Chapter IDs follow the existing course roadmap: 4 numbers, 5 calendar, 6 time,
7 nouns/articles, 8 pronouns/ser, 9 ter/possession, 10 adjectives, 11 family,
12 colours/objects, 13 food, 14 present routines, 15 revision, 91 sentence
patterns, and 92 possessives/demonstratives.
"""

def _q(prompt, options, answer, explanation):
    return (prompt, options, answer, explanation)

def _lesson(title, goal, objectives, vocabulary, grammar, expressions, examples,
            conversations, pronunciation, exercises, assessment, speaking,
            summary, homework):
    vocab = [(w, meaning, hint, "—", example) for w, meaning, hint, example in vocabulary]
    return {
        "title": title, "goal": goal, "objectives": objectives,
        "vocabulary": vocab, "grammar": grammar, "expressions": expressions,
        "examples": examples, "conversations": conversations,
        "pronunciation": pronunciation + [
            "Angolan Portuguese varies by region, speaker and situation; these notes are practical guidance, not a single required accent."
        ],
        "exercises": exercises, "assessment": assessment,
        "speaking": speaking, "summary": summary, "homework": homework,
    }

